#
# collect-stand-logs.sh — журналы стенда в артефакт, перечнем, ВЫВЕДЕННЫМ ИЗ
# ПОДНЯТОГО КЛАСТЕРА, а не выписанным в конвейере.
#
# ─── ПРЕДМЕТ (#1741) ────────────────────────────────────────────────────────
#
# Здесь стоял перечень имён, выписанный в теле шага — и выписанный ДВАЖДЫ (сбор
# в артефакт и хвост в журнал работы). Он называл восемь наших служб и не
# называл службу личности, её курьера и провайдера токенов, поднимаемых тем же
# чартом. Следствие: когда ломается полоса личности, ЕДИНСТВЕННЫЙ журнал, где
# названа причина, выбрасывается вместе с кластером.
#
# Цена измерена, а не предположена: строка отказа обратного хука доставалась
# разбирающему только потому, что он успел к артефакту раньше сноса стенда. В
# обычном случае её нет вовсе, и половина захода уходит на опровержение неверных
# версий причины — упавшая база, деградация ранера, размер пула, — каждая из
# которых объяснялась бы иначе, будь журнал под рукой.
#
# ОТСУТСТВУЮЩИЙ ЖУРНАЛ НЕ ДАЁТ НИ КРАСНОГО, НИ ЗЕЛЁНОГО. Он делает разбор дороже
# прогона — тот же класс, что «ноль находок неотличим от ноль прочитанного»,
# только на уровне оснастки.
#
# ─── ЧТО ЗДЕСЬ ВЕРНО BY CONSTRUCTION ────────────────────────────────────────
#
# Перечень спрашивается У КЛАСТЕРА. Значит «служба поднята и не попала в сбор»
# невозможна иначе как отказом чтения её журнала — а он называется по имени и
# считается отдельно. Новая служба в чарте попадает в сбор, не требуя правки
# конвейера; снятая — исчезает из него, не оставляя мёртвого имени.
#
# ЧИСЛА ПЕЧАТАЮТСЯ РЯДОМ. «Журналы собраны» обязано быть отличимо от «собраны не
# все», поэтому перепись называет: поднято · собрано · пусто · недоступно. Ноль
# поднятых — отдельная строка, а не тишина.
#
# ─── ПОЧЕМУ СКРИПТ НЕ ПАДАЕТ ────────────────────────────────────────────────
#
# Он диагностика, а не вердикт. Второе красное рядом с настоящей причиной делает
# один отказ похожим на два (#728) — тот же довод, что у соседнего
# `stand-present-or-explain.sh`. Недоступный журнал поэтому даёт аннотацию
# `::warning`, а не код возврата. Отличить «собрали не всё» от «всё хорошо» можно
# по числам, и они печатаются всегда.
#
# ─── КАК ЗВАТЬ ──────────────────────────────────────────────────────────────
#
#   .github/scripts/collect-stand-logs.sh <namespace> <каталог> [хвост]
#
# Код возврата у шага не читается как условие продолжения: тело шага GitHub
# исполняет под `bash -e`, и рабочая логика, полагающаяся на код возврата,
# оборвалась бы молча до первой развилки. Здесь развилок в конвейере нет вовсе —
# они внутри скрипта.

set -u

ns="${1:-kacho}"
out="${2:-stand-logs}"
tail_lines="${3:-20000}"

mkdir -p "$out"

# Перечень — ИЗ КЛАСТЕРА. Читаются оба вида носителей: сервисы едут
# Deployment'ами, хранилища и реестр образов — StatefulSet'ами, и перечень одного
# вида молча терял бы половину стенда.
workloads=$(kubectl -n "$ns" get deploy,statefulset -o name 2>/dev/null) && rc=0 || rc=$?

if [ "$rc" -ne 0 ] || [ -z "$workloads" ]; then
    printf 'ЖУРНАЛЫ СТЕНДА: поднятых носителей в пространстве %q не названо ни одного (код %d).\n' \
        "$ns" "$rc"
    printf '::warning title=Журналы стенда не собраны::Кластер не назвал ни одного Deployment/StatefulSet в пространстве %s — собирать нечего. Это не вердикт о продукте: причина названа шагом, который поднимал стенд.\n' "$ns"
    raised=0
else
    raised=$(printf '%s\n' "$workloads" | grep -c .)
fi

collected=0
empty=0
unavailable=0
missing_names=""

for obj in $workloads; do
    # `deployment.apps/kacho-iam` → `kacho-iam`; вид сохраняем в имени файла,
    # чтобы одноимённые носители разных видов не затирали друг друга.
    kind=${obj%%/*}
    kind=${kind%%.*}
    name=${obj##*/}
    file="$out/${kind}-${name}.log"

    # `--all-containers` — курьер и мигратор живут отдельными контейнерами, и
    # чтение одного «главного» теряло бы ровно их. `--prefix` называет, чей это
    # контейнер: без него слитый журнал двух контейнеров неразбираем.
    if kubectl -n "$ns" logs "$obj" --all-containers --prefix --tail="$tail_lines" \
        > "$file" 2>"$file.err"; then
        rm -f "$file.err"
        if [ -s "$file" ]; then
            collected=$((collected + 1))
        else
            empty=$((empty + 1))
            collected=$((collected + 1))
        fi
    else
        unavailable=$((unavailable + 1))
        missing_names="${missing_names} ${kind}/${name}"
        # Причина уезжает В АРТЕФАКТ, а не только в журнал работы: артефакт
        # читают отдельно от него, и пустая выкладка там неотличима от потери.
        {
            printf '(журнал недоступен) %s\n' "$obj"
            head -5 "$file.err" 2>/dev/null
        } > "$file"
        rm -f "$file.err"
    fi
done

kubectl -n "$ns" get events --sort-by=.lastTimestamp > "$out/events.txt" 2>&1 ||
    printf '(события недоступны)\n' > "$out/events.txt"

# ПЕРЕПИСЬ. Оба числа рядом: одно скрывает ровно тот случай, ради которого
# сбор и заведён.
printf '=== журналы стенда: поднято %d · собрано %d · из них пусто %d · недоступно %d\n' \
    "$raised" "$collected" "$empty" "$unavailable"
if [ "$raised" -gt 0 ]; then
    find "$out" -maxdepth 1 -type f -printf '    %f\n' | sort
fi

if [ "$unavailable" -gt 0 ]; then
    printf '::warning title=Журналы собраны НЕ ПОЛНОСТЬЮ::Поднято %d носителей, журнал недоступен у %d:%s. Разбор по этим службам пойдёт без их журнала.\n' \
        "$raised" "$unavailable" "$missing_names"
fi

exit 0
